135	 */
136	export function withSpan<T>(
137	  callback: (span: LiveSpan) => T | Promise<T>,
138	  options?: Omit<SpanOptions, 'parent'>,
139	): T | Promise<T> {
140	  if (isTracingEnabledInContext() === false) {
141	    return callback(new NoOpSpan());
142	  }
143	
144	  const spanOptions: Omit<SpanOptions, 'parent'> = options ?? { name: DEFAULT_SPAN_NAME };
145	
146	  // Generate a default span name if not provided
147	  const spanName = spanOptions.name || DEFAULT_SPAN_NAME;
148	
149	  const tracer = getTracer('default');
150	
151	  // Convert startTimeNs to OTel format if provided
152	  const startTime = spanOptions.startTimeNs
153	    ? convertNanoSecondsToHrTime(spanOptions.startTimeNs)
154	    : undefined;
155	
156	  // Use startActiveSpan to automatically manage context and parent-child relationships
157	  return tracer.startActiveSpan(spanName, { startTime }, (otelSpan: ApiSpan) => {
