159	
160	    try {
161	      // SpanProcessor should have already registered the mlflow span
162	      mlflowSpan = getMlflowSpan(otelSpan as OTelSpan, spanOptions);
163	    } catch (error) {
164	      console.debug('Failed to create and register MLflow span', error);
165	      mlflowSpan = new NoOpSpan();
166	    }
167	
168	    // Expression function to handle errors consistently
169	    const handleError = (error: Error): never => {
170	      try {
171	        mlflowSpan.setStatus(SpanStatusCode.ERROR, error.message);
172	        mlflowSpan.recordException(error);
173	        mlflowSpan.end();
174	      } catch (error) {
175	        console.debug('Failed to set status or record exception on MLflow span', error);
176	      }
177	      throw error;
178	    };
179	
180	    try {
181	      // Execute the callback with the span
182	      const result = callback(mlflowSpan);
183	
184	      // Handle both sync and async results
185	      if (result instanceof Promise) {
186	        return result
187	          .then((value) => {
188	            // Set outputs if they are not already set
189	            if (mlflowSpan.outputs === undefined) {
190	              mlflowSpan.setOutputs(value);
191	            }
192	            mlflowSpan.end();
193	            return value;
194	          })
195	          .catch(handleError);
196	      } else {
197	        // Synchronous execution
198	        if (mlflowSpan.outputs === undefined) {
199	          mlflowSpan.setOutputs(result);
200	        }
201	        mlflowSpan.end();
202	        return result;
203	      }
204	    } catch (error) {
205	      // Handle synchronous errors
206	      return handleError(error as Error);
207	    }
208	  });
