export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  [key: string]: unknown;
}

/** Payload on a `progress` entry describing a sub-agent step. */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  message: TranscriptEntry;
  [key: string]: unknown;
}

