 * Transcript parsing utilities for Claude Code JSONL files.
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

/** Read and parse a Claude Code JSONL transcript file, one entry per line. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

const NANOSECONDS_PER_MS = 1e6;
const NANOSECONDS_PER_SECOND = 1e9;

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * - `null`, `undefined`, and empty string return `null`.
 * - ISO date strings are parsed via `Date` and scaled to nanoseconds; strings
 *   that are not valid dates return `null`.
 * - Numeric values are interpreted by magnitude: `>= 1e13` are already
 *   nanoseconds, `>= 1e10` are milliseconds, and anything smaller is treated
 *   as Unix seconds. Each returns `Math.floor` of the scaled value.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (!Number.isFinite(ts)) {
      return null;
    }
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_SECOND);
  }

  const ms = new Date(ts).getTime();
  if (Number.isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content value. A string is returned
 * unchanged. An array of content blocks yields the `text` fields of all blocks
 * whose type is `text`, joined with newlines. An empty array returns `''`.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: unknown }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (!Array.isArray(content)) {
    return '';
  }
  return content
    .filter((block) => block && block.type === 'text')
    .map((block) => (typeof block.text === 'string' ? block.text : ''))
    .join('\n');
}

/**
 * Whether an entry is a "real" user message — a typed prompt, not a tool
 * result, compact summary, or skill-injection message.
 */
export function isRealUserMessage(entry: TranscriptEntry): boolean {
  if (!entry || entry.type !== 'user') {
    return false;
  }
  if (entry.isCompactSummary === true) {
    return false;
  }

  const content = entry.message?.content;

  // Tool results arrive as user entries whose content is an array of
  // tool_result blocks — those are not real user prompts.
  if (Array.isArray(content) && content.some((block) => block?.type === 'tool_result')) {
    return false;
  }

  // Skill injections are prepended user messages that start with a fixed
  // marker describing the working directory.
  const text = extractTextContent((content ?? '') as ContentBlock[] | string);
  if (text.startsWith('Base directory:')) {
    return false;
  }

  return true;
}

/**
 * Find the index of the last real user message in the transcript, or `null`
 * if there is none (including when `entries` is empty).
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Search from `startIndex` onward and return the extracted text of the last
 * assistant entry that has text content, or `null` if none exists.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let result: string | null = null;
  for (let i = Math.max(0, startIndex); i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant') {
      continue;
    }
    const text = extractTextContent((entry.message?.content ?? '') as ContentBlock[] | string);
    if (text.trim()) {
      result = text;
    }
  }
  return result;
}
