 * Types for Claude Code transcript parsing.
 *
 * Claude Code writes conversation transcripts as JSONL files (one JSON object
 * per line) under `~/.claude/projects/<project>/<sessionId>.jsonl`. Each line
 * is a `TranscriptEntry`. The entries relevant to tracing are:
 *
 *   - `user`      — a user turn. `message.content` is either a plain string
 *                   (the typed prompt) or an array of content blocks. Tool
 *                   results are delivered as `user` entries whose content is an
 *                   array of `tool_result` blocks.
 *   - `assistant` — an assistant turn. `message.content` is an array of blocks
 *                   (`text`, `thinking`, `tool_use`). `message.usage` carries
 *                   token counts and `message.model` the model id.
 *   - `progress`  — an inline sub-agent progress event. `parentToolUseID`
 *                   points at the `Task` tool_use that spawned the sub-agent,
 *                   and `data.message` carries one nested `TranscriptEntry` of
 *                   the sub-agent's conversation.
 *   - `queue-operation` — a queued user input. `operation === 'enqueue'`
 *                   entries carry the queued text in `content`.
 */

/** A text content block. */
export interface TextBlock {
  type: 'text';
  text: string;
  [key: string]: unknown;
}

/** A tool invocation requested by the assistant. */
export interface ToolUseBlock {
  type: 'tool_use';
  id: string;
  name: string;
  input: Record<string, unknown>;
  [key: string]: unknown;
}

/** A tool result delivered back to the model (inside a `user` entry). */
export interface ToolResultBlock {
  type: 'tool_result';
  tool_use_id: string;
  content: string | ContentBlock[];
  is_error?: boolean;
  [key: string]: unknown;
}

/**
 * A single content block. Beyond the three shapes above, transcripts may
 * contain other block types (e.g. `thinking`, `image`); they are represented
 * by the open-ended fallback member.
 */
export type ContentBlock =
  | TextBlock
  | ToolUseBlock
  | ToolResultBlock
  | { type: string; text?: string; [key: string]: unknown };

/** Token usage reported on an assistant message. */
export interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  [key: string]: unknown;
}

/** The `message` envelope on `user` and `assistant` entries. */
export interface TranscriptMessage {
  role: string;
  content: string | ContentBlock[];
  model?: string;
  usage?: Usage;
  [key: string]: unknown;
}

/**
 * Metadata attached to a tool result on the enclosing `user` entry. Task tool
 * results carry an `agentId` linking to the sub-agent's sidecar transcript.
 */
export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  [key: string]: unknown;
}

/** Payload on a `progress` entry describing a sub-agent step. */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  message: TranscriptEntry;
  [key: string]: unknown;
}

/**
 * A single entry in a Claude Code JSONL transcript.
 */
export interface TranscriptEntry {
  type: 'user' | 'assistant' | 'progress' | 'queue-operation' | string;
  message?: TranscriptMessage;
  timestamp?: string | number;
  sessionId?: string;
  agentId?: string;
  version?: string;
  permissionMode?: string;
  isCompactSummary?: boolean;
  toolUseResult?: ToolUseResult;
  /** Present on `progress` entries. */
  parentToolUseID?: string;
  toolUseID?: string;
  data?: ProgressData;
  /** Present on `queue-operation` entries. */
  operation?: string;
  content?: string;
  [key: string]: unknown;
}

/**
 * Stop hook input received via stdin.
 *
 * Claude Code fires the Stop hook with a JSON payload:
 *   {"session_id": "...", "transcript_path": "...", "cwd": "...", ...}
 */
export interface StopHookInput {
  session_id: string;
  transcript_path: string | null;
  cwd?: string;
  hook_event_name?: string;
  [key: string]: unknown;
}
